import { useEffect, useMemo, useState } from "react";
import { AlertCircle, ArrowRight, BookOpen, CalendarDays, CheckCircle2, ClipboardList, Clock3, Download, GraduationCap, LockKeyhole, Pencil, Plus, Printer, Search, Trash2, Moon, Sun, Paperclip, Link2 } from "lucide-react";
import { Link } from "wouter";
import { trpc } from "@/lib/trpc";

const dayNames = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت"];
const schoolName = "اسم المدرسة";
function daysLeft(date: string) { const now = new Date(); const today = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()); const due = new Date(`${date}T00:00:00`); const dueDay = Date.UTC(due.getFullYear(), due.getMonth(), due.getDate()); return Math.ceil((dueDay - today) / 86400000); }
type ResourceEdit = { kind: "assignment" | "lesson" | "academic"; academicKind?: "exam" | "research"; id: number; title: string; description?: string | null; dueDate?: string; lessonDate?: string; page?: string | null; notes?: string | null; attachmentUrl?: string | null; attachmentName?: string | null; resourceUrl?: string | null };
async function fileToDataUrl(file: File) { return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("تعذر قراءة الملف")); reader.readAsDataURL(file); }); }
function daysLabel(date: string) { const days = daysLeft(date); if (days === 0) return "التسليم اليوم"; if (days > 0) return `متبقي ${days} ${days === 1 ? "يوم" : "أيام"}`; const late = Math.abs(days); return `متأخر ${late} ${late === 1 ? "يوم" : "أيام"}`; }
function assignmentCardClass(date: string) { const days = daysLeft(date); if (days < 0) return "rounded-2xl border border-rose-200 bg-rose-50 p-4"; if (days <= 2) return "rounded-2xl border border-amber-200 bg-amber-50 p-4"; return "rounded-2xl border border-emerald-200 bg-emerald-50/50 p-4"; }
export function StudentPortal() {
  const { data, isLoading, error } = trpc.school.content.useQuery();
  const [studentName, setStudentName] = useState(() => localStorage.getItem("wusool-student-name") || "");
  const [lightMode, setLightMode] = useState(() => localStorage.getItem("wusool-theme") === "light");
  const toggleTheme = () => { const next = !lightMode; setLightMode(next); localStorage.setItem("wusool-theme", next ? "light" : "dark"); };
  const [nameDraft, setNameDraft] = useState("");
  const [selectedSubject, setSelectedSubject] = useState<number | null>(null);
  const [search, setSearch] = useState("");
  const [assignmentFilter, setAssignmentFilter] = useState<"all" | "overdue" | "near" | "far">("all");
  const [dateFrom, setDateFrom] = useState(""); const [dateTo, setDateTo] = useState("");
    const today = new Date().getDay(); const [selectedDay, setSelectedDay] = useState(today);
  const subjects = data?.subjects ?? []; const assignmentsAll = data?.assignments ?? []; const lessonsAll = data?.lessons ?? []; const academicItems = data?.academicItems ?? [];
  const alerts = assignmentsAll.filter(a => daysLeft(a.dueDate) <= 2);
  const filteredSubjects = subjects.filter(s => s.name.includes(search.trim()));
  const current = selectedSubject ?? filteredSubjects[0]?.id ?? subjects[0]?.id;
  const subject = subjects.find(s => s.id === current);
  const todaySchedule = useMemo(() => (data?.schedule ?? []).filter(item => item.dayOfWeek === selectedDay).sort((a, b) => a.period - b.period), [data, selectedDay]);
  const lessons = lessonsAll.filter(item => item.subjectId === current); const assignments = assignmentsAll.filter(item => item.subjectId === current); const exams = academicItems.filter(item => item.subjectId === current && item.kind === "exam"); const researches = academicItems.filter(item => item.subjectId === current && item.kind === "research");
  const visibleAssignments = assignments.filter(a => { const inRange = (!dateFrom || a.dueDate >= dateFrom) && (!dateTo || a.dueDate <= dateTo); const status = assignmentFilter === "all" || (assignmentFilter === "overdue" && daysLeft(a.dueDate) < 0) || (assignmentFilter === "near" && daysLeft(a.dueDate) >= 0 && daysLeft(a.dueDate) <= 2) || (assignmentFilter === "far" && daysLeft(a.dueDate) > 2); return inRange && status; });
  const saveName = (e: React.FormEvent) => { e.preventDefault(); const value = nameDraft.trim(); if (value.length < 2) return; localStorage.setItem("wusool-student-name", value); setStudentName(value); setNameDraft(""); };
  const changeName = () => { setNameDraft(studentName); setStudentName(""); localStorage.removeItem("wusool-student-name"); };
  if (isLoading) return <div className="flex min-h-screen items-center justify-center bg-[#071a33] text-sm font-bold text-white">جارٍ تحميل بيانات وصول...</div>;
  if (!studentName) return <NameGate value={nameDraft} onChange={setNameDraft} onSubmit={saveName} />;
  return <main dir="rtl" className={`wusool-design01 min-h-screen bg-[#071a33] text-white ${lightMode ? "light-mode" : ""}`}><header className="no-print sticky top-0 z-20 border-b border-white/10 bg-[#071a33]/95 backdrop-blur"><div className="mx-auto flex max-w-[1500px] items-center justify-between gap-4 px-4 py-4 sm:px-8"><div className="flex items-center gap-3"><span className="brand-mark flex h-12 w-12 items-center justify-center rounded-2xl text-white"><GraduationCap className="h-6 w-6" /></span><div><p className="font-display text-xl font-bold">وصول</p><p className="text-[10px] font-bold tracking-[.18em] text-emerald-300">منصة المدرسة</p></div></div><div className="flex items-center gap-2"><span className="hidden text-xs font-bold text-slate-300 sm:inline">مرحبًا، {studentName}</span><ThemeToggle lightMode={lightMode} onToggle={toggleTheme} /><button type="button" onClick={changeName} className="rounded-xl border border-white/15 px-3 py-2 text-xs font-bold text-slate-200 hover:border-emerald-300 hover:text-emerald-200">تغيير الاسم</button><button type="button" onClick={() => window.print()} className="inline-flex items-center gap-2 rounded-xl bg-emerald-400 px-3 py-2 text-xs font-bold text-[#062b2a] hover:bg-emerald-300"><Printer className="h-4 w-4" />تصدير PDF</button></div></div></header><div className="print-only mx-auto max-w-7xl border-b-2 border-emerald-600 pb-4 text-center text-slate-900"><div className="flex items-center justify-center gap-3"><span className="brand-mark flex h-12 w-12 items-center justify-center rounded-2xl text-white"><GraduationCap className="h-6 w-6" /></span><div><h1 className="font-display text-2xl font-bold">منصة وصول</h1><p className="text-sm font-bold text-slate-600">{schoolName}</p></div></div><p className="mt-2 text-sm font-bold text-slate-500">تقرير جدول الحصص والواجبات — {studentName}</p></div><div className="mx-auto max-w-[1500px] space-y-6 px-4 py-6 sm:px-8"><section className="rounded-[30px] border border-white/10 bg-gradient-to-br from-[#102d52] via-[#0d2443] to-[#0a1b35] p-6 shadow-2xl shadow-black/20 sm:p-8"><div className="flex flex-col justify-between gap-6 lg:flex-row lg:items-end"><div><p className="mb-2 text-sm font-bold text-emerald-300">{dayNames[today]} · جدولك اليومي</p><h1 className="font-display text-3xl font-bold sm:text-5xl">أهلًا {studentName}،<br />خلّ يومك أسهل.</h1><p className="mt-4 max-w-xl text-sm leading-7 text-slate-300">كل ما تحتاجه من جدول ومواد ودروس وواجبات واختبارات وبحوث في لوحة واحدة.</p><Link href="/manage" className="mt-5 inline-flex items-center gap-2 rounded-xl bg-emerald-400 px-4 py-3 text-sm font-bold text-[#062b2a] hover:bg-emerald-300"><LockKeyhole className="h-4 w-4" />صفحة الإدارة</Link></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-3"><MiniStat label="المواد" value={subjects.length} icon={<BookOpen className="h-4 w-4" />} /><MiniStat label="الواجبات" value={assignmentsAll.length} icon={<ClipboardList className="h-4 w-4" />} /><MiniStat label="التنبيهات" value={alerts.length} icon={<AlertCircle className="h-4 w-4" />} /></div></div></section>{alerts.length > 0 && <section className="student-alerts rounded-2xl border border-amber-300/30 bg-amber-300/10 p-4 text-amber-100"><div className="flex items-start gap-3"><AlertCircle className="mt-0.5 h-5 w-5 shrink-0 text-amber-300" /><div><p className="font-bold">تنبيهات الواجبات</p><div className="mt-1 space-y-1 text-sm">{alerts.slice(0, 4).map(a => <p key={a.id}>{a.title}: <b>{daysLabel(a.dueDate)}</b></p>)}</div></div></div></section>}<section className="grid gap-5 xl:grid-cols-[1.6fr_1fr]"><div className="rounded-[28px] bg-[#f8f6f0] p-5 text-slate-900 shadow-xl sm:p-7"><div className="mb-5 flex items-end justify-between"><div><p className="text-sm font-bold text-emerald-700">اختر يومًا لعرض جدوله</p><h2 className="font-display text-2xl font-bold">الجدول اليومي</h2></div><CalendarDays className="h-7 w-7 text-emerald-600" /></div><div className="no-print mb-5 grid grid-cols-5 gap-2">{dayNames.slice(0, 5).map((name, day) => <button key={name} onClick={() => setSelectedDay(day)} className={`rounded-xl border p-3 text-center text-xs font-bold transition ${selectedDay === day ? "border-emerald-500 bg-emerald-500 text-white" : "border-slate-200 bg-white text-slate-600 hover:border-emerald-300"}`}><span className="block">{name}</span>{day === today && <small className="mt-1 block text-[10px]">اليوم</small>}</button>)}</div>{todaySchedule.length === 0 ? <Empty text="لم تتم إضافة جدول لهذا اليوم بعد." /> : <div className="grid gap-3 sm:grid-cols-2">{todaySchedule.map(item => { const s = subjects.find(x => x.id === item.subjectId); return <button key={item.id} onClick={() => setSelectedSubject(item.subjectId)} className="card-hover rounded-2xl border border-slate-200 bg-white p-4 text-right shadow-sm"><div className="flex items-center justify-between"><span className="rounded-lg bg-emerald-50 px-2 py-1 text-xs font-bold text-emerald-700">الحصة {item.period}</span><Clock3 className="h-4 w-4 text-slate-300" /></div><p className="mt-4 font-display text-lg font-bold">{s?.name || "مادة"}</p><p className="mt-1 text-xs text-slate-500">{item.startTime} - {item.endTime}{item.room ? ` · ${item.room}` : ""}</p></button>; })}</div>}</div><aside className="rounded-[28px] border border-white/10 bg-[#102d52] p-5 shadow-xl sm:p-7"><div className="mb-4 flex items-center justify-between"><div><p className="text-sm font-bold text-emerald-300">موادك الدراسية</p><h2 className="font-display text-2xl font-bold">المواد</h2></div><span className="text-xs text-slate-400">{subjects.length} مواد</span></div><label className="no-print relative mb-4 block"><Search className="pointer-events-none absolute right-3 top-3 h-4 w-4 text-slate-400" /><input className="h-11 w-full rounded-xl border border-white/10 bg-[#071a33] pr-9 pl-3 text-sm text-white outline-none placeholder:text-slate-500 focus:border-emerald-400" value={search} onChange={e => setSearch(e.target.value)} placeholder="ابحث عن مادة..." /></label><div className="grid gap-2">{filteredSubjects.map(s => { const sl=lessonsAll.filter(l=>l.subjectId===s.id).length, sa=assignmentsAll.filter(a=>a.subjectId===s.id).length; return <button key={s.id} onClick={() => setSelectedSubject(s.id)} className={`rounded-2xl border p-4 text-right transition ${current===s.id ? "border-emerald-400 bg-emerald-500 text-[#062b2a]" : "border-white/10 bg-[#0b2342] text-white hover:border-emerald-300"}`}><p className="font-bold">{s.name}</p><p className={`mt-1 text-xs ${current===s.id ? "text-emerald-950/70" : "text-slate-400"}`}>{s.teacherName ? `المعلم: ${s.teacherName} · ` : ""}{sl} دروس · {sa} واجبات</p></button>; })}</div></aside></section><section className="rounded-[28px] bg-[#f8f6f0] p-5 text-slate-900 shadow-xl sm:p-7"><div className="mb-5 flex flex-col justify-between gap-3 border-b border-slate-200 pb-5 sm:flex-row sm:items-center"><div><p className="text-sm font-bold text-emerald-700">محتوى المادة</p><h2 className="font-display text-2xl font-bold">{subject?.name || "اختر مادة"}</h2></div>{subject && <span className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-slate-500">{lessons.length} دروس · {assignments.length} واجبات</span>}</div>{subject ? <div className="grid gap-6 xl:grid-cols-2"><div><div className="mb-3 flex items-center gap-2"><BookOpen className="h-4 w-4 text-emerald-600" /><h3 className="font-bold">الدروس التي أُخذت</h3></div>{lessons.length===0?<Empty text="لا توجد دروس مسجلة لهذه المادة." />:<div className="space-y-3">{lessons.map(l=><article key={l.id} className="rounded-2xl bg-white p-4 shadow-sm"><div className="flex justify-between gap-3"><h4 className="font-bold">{l.title}</h4><span className="text-xs text-slate-400">{l.lessonDate}</span></div>{l.page&&<p className="mt-2 text-xs font-semibold text-emerald-700">صفحة: {l.page}</p>}{l.notes&&<p className="mt-2 text-sm leading-6 text-slate-600">{l.notes}</p>}{(l.attachmentUrl || l.resourceUrl) && <div className="mt-3 flex flex-wrap gap-2">{l.attachmentUrl && <a href={l.attachmentUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-lg bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-800"><Download className="h-4 w-4" />{l.attachmentName || "فتح مرفق الدرس"}</a>}{l.resourceUrl && <a href={l.resourceUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-lg bg-sky-50 px-3 py-2 text-xs font-bold text-sky-800"><Link2 className="h-4 w-4" />فتح رابط الدرس</a>}</div>}</article>)}</div>}</div><div><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div className="flex items-center gap-2"><ClipboardList className="h-4 w-4 text-amber-600" /><h3 className="font-bold">الواجبات</h3></div><select className="no-print rounded-lg border border-slate-200 bg-white px-2 py-1 text-xs font-bold text-slate-600" value={assignmentFilter} onChange={e=>setAssignmentFilter(e.target.value as typeof assignmentFilter)}><option value="all">كل الواجبات</option><option value="overdue">متأخرة</option><option value="near">قريبة</option><option value="far">بعيدة</option></select></div>{assignments.length===0?<Empty text="لا يوجد واجب لهذه المادة حاليًا." />:visibleAssignments.length===0?<Empty text="لا توجد واجبات بهذه الحالة." />:<div className="space-y-3">{visibleAssignments.map(a=><article key={a.id} className={`${assignmentCardClass(a.dueDate)} shadow-sm`}><div className="flex flex-wrap items-center justify-between gap-2"><h4 className="font-bold">{a.title}</h4><span className="text-xs font-bold">{daysLabel(a.dueDate)} · {a.dueDate}</span></div>{a.description&&<p className="mt-2 text-sm leading-6 text-slate-600">{a.description}</p>}{a.attachmentUrl&&<a href={a.attachmentUrl} target="_blank" rel="noreferrer" className="mt-3 inline-flex items-center gap-2 rounded-lg bg-white px-3 py-2 text-xs font-bold text-emerald-700"><Download className="h-4 w-4" />{a.attachmentName||"فتح المرفق"}</a>}{a.resourceUrl&&<a href={a.resourceUrl} target="_blank" rel="noreferrer" className="mt-3 mr-2 inline-flex items-center gap-2 rounded-lg bg-sky-50 px-3 py-2 text-xs font-bold text-sky-800"><Link2 className="h-4 w-4" />فتح الرابط</a>}</article>)}</div>}</div></div>:<Empty text="اختر مادة لعرض محتواها." />}</section><section className="grid gap-5 xl:grid-cols-2"><AcademicList title="الاختبارات" items={exams} empty="لا توجد اختبارات مسجلة لهذه المادة." tone="violet" /><AcademicList title="البحوث" items={researches} empty="لا توجد بحوث مسجلة لهذه المادة." tone="teal" /></section>{error&&<p className="text-sm font-bold text-rose-300">تعذر تحميل البيانات. تأكد من اتصال النظام.</p>}<CopyrightFooter /></div></main>;
}
function NameGate({ value, onChange, onSubmit }: { value: string; onChange: (value: string) => void; onSubmit: (event: React.FormEvent) => void }) { return <main dir="rtl" className="flex min-h-screen items-center justify-center bg-[#071a33] px-4"><section className="w-full max-w-md rounded-[32px] border border-white/10 bg-[#102d52] p-7 text-white shadow-2xl sm:p-10"><div className="mb-8 text-center"><span className="brand-mark mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-3xl text-white"><GraduationCap className="h-8 w-8" /></span><p className="text-sm font-bold text-emerald-300">أول مرة هنا؟</p><h1 className="mt-2 font-display text-3xl font-bold">أهلًا بك في وصول</h1><p className="mt-3 text-sm leading-7 text-slate-300">اكتب اسمك ليظهر لك في بداية الموقع. سيُحفظ الاسم على هذا الجهاز فقط.</p></div><form onSubmit={onSubmit} className="space-y-4"><label className="block"><span className="mb-2 block text-sm font-bold">اسم الطالب</span><input required minLength={2} autoFocus className="h-12 w-full rounded-xl border border-white/10 bg-[#071a33] px-4 text-white outline-none placeholder:text-slate-500 focus:border-emerald-400" value={value} onChange={e => onChange(e.target.value)} placeholder="مثال: محمد أحمد" /></label><button type="submit" className="h-12 w-full rounded-xl bg-emerald-400 font-bold text-[#062b2a] hover:bg-emerald-300">الدخول إلى وصول</button></form></section></main> }
function CopyrightFooter() { return <footer className="copyright-footer no-print mt-8 border-t border-white/10 py-5 text-center text-xs font-semibold text-slate-400">حقوق النشر © 2026 أسامة سامي · منصة وصول</footer>; }

function MiniStat({ label, value, icon }: { label: string; value: number; icon: React.ReactNode }) { return <div className="rounded-2xl border border-white/10 bg-white/5 px-4 py-3"><div className="mb-2 flex items-center gap-2 text-emerald-300">{icon}<span className="text-xs font-bold">{label}</span></div><strong className="font-display text-2xl">{value}</strong></div> }
function ThemeToggle({ lightMode, onToggle }: { lightMode: boolean; onToggle: () => void }) { return <button type="button" onClick={onToggle} aria-label={lightMode ? "تفعيل الوضع الداكن" : "تفعيل الوضع الفاتح"} className="inline-flex items-center gap-2 rounded-xl border border-emerald-300/30 bg-emerald-300/10 px-3 py-2 text-xs font-bold text-emerald-200 hover:bg-emerald-300/20">{lightMode ? <Moon className="h-4 w-4" /> : <Sun className="h-4 w-4" />}<span className="hidden sm:inline">{lightMode ? "الوضع الداكن" : "الوضع الفاتح"}</span></button> }
function Empty({ text }: { text: string }) { return <div className="rounded-2xl border border-dashed border-slate-200 bg-white p-5 text-center text-xs leading-6 text-slate-500">{text}</div>; }


function AcademicList({ title, items, empty, tone }: { title: string; items: { id: number; title: string; description?: string | null; dueDate: string; attachmentUrl?: string | null; attachmentName?: string | null; resourceUrl?: string | null }[]; empty: string; tone: "violet" | "teal" }) { const toneClass = tone === "violet" ? "border-violet-200 bg-violet-50" : "border-teal-200 bg-teal-50"; return <section className={`academic-section rounded-[28px] border p-5 shadow-sm ${toneClass}`}><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-xl font-bold text-slate-900">{title}</h2><span className="rounded-lg bg-white px-2 py-1 text-xs font-bold text-slate-500">{items.length}</span></div>{items.length === 0 ? <div className="academic-empty rounded-2xl bg-white/70 p-4 text-center text-xs text-slate-500">{empty}</div> : <div className="space-y-3">{items.map(item => <article key={item.id} className="academic-card rounded-2xl bg-white p-4 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-bold text-slate-900">{item.title}</h3><span className="text-xs font-bold text-slate-500">{daysLabel(item.dueDate)} · {item.dueDate}</span></div>{item.description && <p className="mt-2 text-sm leading-6 text-slate-600">{item.description}</p>}{(item.attachmentUrl || item.resourceUrl) && <div className="mt-3 flex flex-wrap gap-2">{item.attachmentUrl && <a href={item.attachmentUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-lg bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-800 hover:bg-emerald-100"><Download className="h-4 w-4" />{item.attachmentName || "فتح المرفق"}</a>}{item.resourceUrl && <a href={item.resourceUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-lg bg-sky-50 px-3 py-2 text-xs font-bold text-sky-800 hover:bg-sky-100"><ArrowRight className="h-4 w-4" />فتح الرابط</a>}</div>}</article>)}</div>}</section> }

const inputClass = "h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm outline-none transition focus:border-teal-400 focus:bg-white focus:ring-4 focus:ring-teal-500/10";
type Tab = "assignment" | "lesson" | "exam" | "research" | "schedule" | "manage";
export function AssignmentEntry() {
  const [username, setUsername] = useState(""); const [code, setCode] = useState(""); const [loginError, setLoginError] = useState("");
  const [lightMode, setLightMode] = useState(() => localStorage.getItem("wusool-theme") === "light");
  const toggleTheme = () => { const next = !lightMode; setLightMode(next); localStorage.setItem("wusool-theme", next ? "light" : "dark"); };
  const utils = trpc.useUtils();
  const { data: currentUser, isLoading } = trpc.auth.me.useQuery();
  const schoolLogin = trpc.auth.schoolLogin.useMutation({ onSuccess: () => { setLoginError(""); utils.auth.me.invalidate(); }, onError: () => setLoginError("رقم الدخول أو كلمة المرور غير صحيحة.") });
  const schoolLogout = trpc.auth.schoolLogout.useMutation({ onSuccess: () => utils.auth.me.invalidate() });
  useEffect(() => {
    const lockOnLeave = () => {
      const body = JSON.stringify({ "0": { json: null } });
      navigator.sendBeacon("/api/trpc/auth.schoolLogout?batch=1", new Blob([body], { type: "application/json" }));
    };
    // pagehide fires only when leaving this page, not when switching apps/tabs or submitting login.
    window.addEventListener("pagehide", lockOnLeave);
    return () => window.removeEventListener("pagehide", lockOnLeave);
  }, []);
  if (isLoading) return <main dir="rtl" className="flex min-h-screen items-center justify-center bg-[#f6f8fb] text-sm font-bold text-slate-500">جارٍ التحقق من الدخول...</main>;
  if (!currentUser) return <LoginGate username={username} code={code} setUsername={setUsername} setCode={setCode} error={loginError} lightMode={lightMode} onToggleTheme={toggleTheme} onSubmit={(e) => { e.preventDefault(); schoolLogin.mutate({ username, password: code }); }} />;
  const lock = async (goHome = false) => { await schoolLogout.mutateAsync(); if (goHome) window.location.assign("/"); };
  return <EntryWorkspace onLock={() => { void lock(false); }} onExit={() => { void lock(true); }} lightMode={lightMode} onToggleTheme={toggleTheme} />;
}
